import pytest
from inventory.pallets import pallet_count


@pytest.mark.l4("C-97b5cb90")
def test_units_fill_whole_pallets():
    """C-97b5cb90: When units divide evenly, return exact count."""
    result = pallet_count(100, 50)
    assert result == 2


@pytest.mark.l4("C-b2a1936c")
def test_partly_filled_last_pallet():
    """C-b2a1936c: When units don't divide evenly, round up."""
    result = pallet_count(101, 50)
    assert result == 3
